<script setup lang="ts">import type{User}from'@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';const items=ref<User[]>([]);const keyword=ref('');async function load(){const term=keyword.value.trim();items.value=(await repository.admin.users.list({...term?{keyword:term}:{},page:1,pageSize:100})).items}async function toggle(item:User){if(!window.confirm(`确认${item.status==='active'?'禁用':'恢复'}用户“${item.nickname}”？`))return;await repository.admin.users.updateStatus(item.id,item.status==='active'?'disabled':'active');await load()}onMounted(load)</script>
<template><section><header class="admin-page-head"><div><h1>用户管理</h1><p>查看学生账号状态并处理异常账号。</p></div></header><div class="admin-toolbar"><input v-model="keyword" placeholder="邮箱、昵称或学校" @keyup.enter="load"/><button class="cl-quiet-button" @click="load">搜索</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>用户</th><th>学校</th><th>学历</th><th>毕业年份</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{item.nickname}}</strong><br/><span class="admin-muted">{{item.email}}</span></td><td>{{item.school}}</td><td>{{item.education}}</td><td>{{item.graduationYear}}</td><td>{{item.status==='active'?'正常':'已禁用'}}</td><td><button class="admin-link-button">查看</button><button class="admin-link-button" @click="toggle(item)">{{item.status==='active'?'禁用':'恢复'}}</button></td></tr></tbody></table></div></section></template>
